// 独立contact_inquiries/1格式，不扩旧Interaction/Task字段；重键、未知字段及派生索引均不被暗中接受。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "contact_inquiry_state.hpp"
#include "resident/domains/interaction/s3_leaf_life_codec.hpp"
#include "resident/domains/interaction/s3_event_time_codec.hpp"
#include "resident/domains/tasks/task_dynamic_codec.hpp"
#include "resident/domains/tasks/task_dynamic_projection.hpp"
#include "resident/domains/interaction/interaction_source_projection.hpp"
namespace hanmo::resident {namespace {
template<class A>Status contact(A& a,ContactInquiryContact& c){a.field("actor_id",c.actor_id);a.field("provider_actor_id",c.provider_actor_id);a.field("session_id",c.session_id);a.field("place_id",c.place_id);a.field("role_id",c.role_id);a.field("dialogue_id",c.dialogue_id);a.field("node_id",c.node_id);return a.field("tick",c.tick);}
template<class A>Status receipt(A& a,std::optional<ContactInquiryPlayerReceipt>& v){return a.optional("player_receipt",v,[](auto& child,auto& p){child.field("result_id",p.result_id);child.field("request_actor_id",p.request_actor_id);child.field("request_sequence",p.request_sequence);return child.field("result_revision",p.result_revision);});}
template<class A>Status started(A& a,ContactInquiryStarted& v){a.field("fact_id",v.fact_id);a.field("policy_id",v.policy_id);a.field("action_id",v.action_id);auto r=a.object("contact",[&](auto& child){return contact(child,v.contact);});return r.ok?receipt(a,v.player_receipt):r;}
template<class A>Status finished(A& a,ContactInquiryFinished& v){a.field("fact_id",v.fact_id);a.field("start_fact_id",v.start_fact_id);a.field("action_id",v.action_id);a.field("tick",v.tick);a.field("success",v.success);a.field("reason",v.reason);a.field("reply_kind",v.reply_kind);auto r=a.optional("answer",v.answer,[](auto& child,auto& p){child.field("subject_actor_id",p.subject_actor_id);child.field("place_id",p.place_id);child.field("source_fact_id",p.source_fact_id);child.field("source_kind",p.source_kind);child.field("observed_tick",p.observed_tick);return child.field("learned_tick",p.learned_tick);});return r.ok?receipt(a,v.player_receipt):r;}
template<class A>Status state(A& a,ContactInquiryState& v){
 a.field("version",v.version);if(v.version!=1&&v.version!=2)return a.reject("UnsupportedContactInquiryVersion");auto r=dynamic_codec::table(a,"started",v.started,[](auto&c,auto&v){return started(c,v);});if(!r.ok)return r;r=dynamic_codec::table(a,"finished",v.finished,[](auto&c,auto&v){return finished(c,v);});if(!r.ok)return r;
 if(v.version==1)return v.life_sources.empty()&&v.temporal_events.empty()?a.status():a.reject("UnselectedContactInquiryTime2Sources");
 r=dynamic_codec::table(a,"life_sources",v.life_sources,[](auto&c,auto&v){c.object("death_ref",[&](auto&x){return s3_leaf_life_codec::death(x,v.death_ref);});c.field("start_fact_id",v.start_fact_id);dynamic_codec::enumeration(c,"role",v.role,1);return c.object("effect",[&](auto&x){return s3_leaf_life_codec::fields(x,v.effect,1);});});if(!r.ok)return r;
 return dynamic_codec::table(a,"temporal_events",v.temporal_events,[](auto&c,auto&v){return s3_event_time_codec::fields(c,v);});
}
// 直接typed JSON也可能带重键；递归拒绝，不能只信外层文本parser。
Status unique(const BoundaryValue& value,std::size_t depth=0){if(depth>CodecVisitor::max_depth)return common_failure("ContactInquiryTooDeep");if(const auto* rows=value.as<BoundaryValue::Dict>()){if(rows->size()>CodecVisitor::max_items)return common_failure("ContactInquiryTooLarge");std::set<StableId> names;for(const auto& row:*rows){if(!names.insert(row.first).second)return common_failure("DuplicateContactInquiryField",row.first);auto r=unique(row.second,depth+1);if(!r.ok)return r;}}if(const auto* rows=value.as<BoundaryValue::Array>()){if(rows->size()>CodecVisitor::max_items)return common_failure("ContactInquiryTooLarge");for(const auto& row:*rows){auto r=unique(row,depth+1);if(!r.ok)return r;}}return common_success();}
}
void rebuild_contact_inquiry_indexes(ContactInquiryState& state){state.by_listener.clear();for(const auto& row:state.started.rows())state.by_listener[row.second.contact.actor_id].push_back(row.first);}
Outcome<ContactInquiryState> decode_contact_inquiries(const BoundaryValue& value){auto r=unique(value);if(!r.ok)return {false,{},r.error};ContactInquiryState out;dynamic_codec::JsonArchive archive(value);r=state(archive,out);if(r.ok)r=archive.finish();if(!r.ok)return {false,{},r.error};rebuild_contact_inquiry_indexes(out);return {true,std::move(out),{}};}
Status emit_contact_inquiries_fields(ProjectionWriter&w,const ContactInquiryState&v){dynamic_projection::Archive a(w);return state(a,const_cast<ContactInquiryState&>(v));}
BoundaryValue encode_contact_inquiries(const ContactInquiryState& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_contact_inquiries_fields(out,s);});if(checked.ok)checked=writer.finish();if(!checked.ok){boundary::DecodeFailure failure(checked.error.original.code,checked.error.original.path);failure.error=checked.error;throw failure;}return value;}
Status visit_contact_inquiries_checkpoint(CodecVisitor& codec,ContactInquiryState& value){auto r=state(codec,value);if(r.ok&&codec.reading())rebuild_contact_inquiry_indexes(value);return r;}
Status emit_contact_inquiry_action_fields(ProjectionWriter&w,const ContactInquiryStarted&s){dynamic_projection::Archive a(w);return started(a,const_cast<ContactInquiryStarted&>(s));}
BoundaryValue encode_contact_inquiry_action(const ContactInquiryStarted& s){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_contact_inquiry_action_fields(out,s);});if(checked.ok)checked=writer.finish();if(!checked.ok){boundary::DecodeFailure failure(checked.error.original.code,checked.error.original.path);failure.error=checked.error;throw failure;}return value;}
Status emit_contact_inquiry_fact_fields(ProjectionWriter&w,const ContactInquiryState&s,const StableId&id,const FactRecord*expected){dynamic_projection::Archive a(w);Status valid;StableId kind;const StableId*actual_id=nullptr;if(const auto*row=s.started.find(id)){valid=started(a,const_cast<ContactInquiryStarted&>(*row));kind=contact_inquiry_started_kind;actual_id=&row->fact_id;}else if(const auto*row=s.finished.find(id)){valid=finished(a,const_cast<ContactInquiryFinished&>(*row));kind=contact_inquiry_finished_kind;actual_id=&row->fact_id;}else return common_failure("MissingContactInquiryPayload",id);if(!valid.ok)return valid;if(expected&&(!actual_id||*actual_id!=id||kind!=expected->kind))return common_failure("ContactInquiryFactMismatch",id);w.field("kind",kind);w.text("domain",std::string_view(contact_inquiry_module));return w.status();}
Outcome<BoundaryValue> encode_contact_inquiry_fact(const ContactInquiryState& s,const StableId& id){BoundaryValue value;BoundaryProjectionWriter writer(value);auto checked=writer.object("",[&](auto& out){return emit_contact_inquiry_fact_fields(out,s,id);});if(checked.ok)checked=writer.finish();return checked.ok?Outcome<BoundaryValue>{true,std::move(value),{}}:Outcome<BoundaryValue>{false,{},checked.error};}
}
